POSTABLE = {"critical", "high", "medium"}

def gate(finding, validator):
    """A finding reaches the PR only with evidence a separate model failed to refute."""
    if not finding.evidence:          # file, line, and a failing input or trace
        return "drop"
    verdict = validator.refute(finding)   # different model, read-only, no tools
    if verdict.refuted:
        return "drop"
    if finding.severity not in POSTABLE:
        return "digest"               # lows and nits never block a merge
    return "post"
